(function(){const countrySelect=$("#id_country");const regionSelect=$("#id_region");if(!countrySelect.val()){regionSelect.prop("disabled",true)}countrySelect.on("change",function(){const countryId=$(this).val();if(!countryId){regionSelect.empty().append('<option value="">---------</option>');regionSelect.prop("disabled",true);return}$.getJSON("/lims/regions/",{country:countryId},function(data){const prevVal=regionSelect.val();regionSelect.empty().append('<option value="">---------</option>');if(data&&data.length>0){$.each(data,function(i,item){const opt=$("<option></option>").attr("value",item.id).text(item.name);if(prevVal&&item.id==prevVal){opt.prop("selected",true)}regionSelect.append(opt)});regionSelect.prop("disabled",false)}else{regionSelect.prop("disabled",true)}})})})();